(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const wx2 = Math.sin(x*0.04-t*0.7)*5 + Math.cos(y*0.035+t*0.6)*4;
  const wy2 = Math.cos(y*0.04+t*0.65)*5 + Math.sin(x*0.03-t*0.55)*4;
  const sx = x+wx+wx2, sy = y+wy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 2],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.75)*55, 0.11, 2.1, 0],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+4)*65, 0.085, 1.8, 1],
    [200+Math.sin(t*0.25+1)*110, 220+Math.cos(t*0.45+3)*40, 0.095, 2.4, 2]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, tp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const dw = Math.sin(d*f*0.5 - t*sp*0.3 + tp*2.1);
    aS += wave + dw*0.3;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.cos(d*f*0.4 + t*sp*0.4 + tp)*0.3;
    wS += Math.sin(d*f*1.3 - t*sp*1.1 + tp*3.14)*0.4;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, wav = wS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.06+sy*0.08-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
