    + Math.sin(dist*0.07-ang*2-t*2.1)*0.5)*0.35;
  const moire = Math.sin(sx*0.09)*Math.sin(sy*0.09) + Math.sin((sx+sy)*0.07-t)*Math.sin((sx-sy)*0.07+t*0.8)*0.5;
  const rd = act - inh*0.7 + bg*0.3 + spiral + wav*0.25 + moire*0.15;
  const reaction = Math.tanh(rd*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend = reaction*0.65 + cell*0.25 + micro;
  const v = blend*0.5+0.5;
  const pal = [[5,10,42],[10,35,75],[12,65,100],[18,110,115],[45,155,130],[130,185,100],[200,195,80],[220,160,75],[200,110,65],[170,65,75],[120,35,65],[65,18,55],[25,10,42],[5,10,42]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.7 ? 1.15 : Math.abs(reaction)>0.4 ? 1.05 : 1.0;
  const glow = Math.max(0, reaction*0.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
